// Implements the fixed-width bank journal and its ledger reports.
export interface RunInput { argv: string[]; stdin: Uint8Array; env: Record<string, string | undefined> }
export interface RunDeps { now(): Date; random(): number; cwd: string; env: Record<string, string | undefined> }
export interface RunOutput { stdout?: string; stderr?: string; exitCode?: number }
interface Entry { account: bigint; balance: bigint; interest: bigint; withdrawals: number; kind: number }

/** Keeps the low 64 bits of a value and returns their signed interpretation. */
function signed(value: bigint): bigint { return BigInt.asIntN(64, value); }

/* LB-BEHAVIOR:feature-1d170d78 */
/** Parses count bytes starting at offset, returning zero for an empty range or minus one for a nondigit; decimal accumulation wraps at 64 bits. */
export function parseDecimalSubstring(bytes: Uint8Array, offset: number, count: number): bigint {
  let value = 0n;
  for (let index = 0; index < count; index++) {
    const digit = (bytes[offset + index] ?? 0) - 48;
    if (digit < 0 || digit > 9) return -1n;
    value = signed(value * 10n + BigInt(digit));
  }
  return value;
}

/* LB-BEHAVIOR:feature-432967e5 */
/** Checks an eight-digit account number using repeating weights two through seven, returning whether its final digit matches. */
export function validateEightDigitMod11Checksum(account: bigint): boolean {
  if (account < 10000000n || account >= 100000000n) return false;
  let remaining = account;
  let weight = 2n;
  let sum = 0n;
  do {
    remaining /= 10n;
    sum += remaining % 10n * weight;
    weight = weight === 7n ? 2n : weight + 1n;
  } while (remaining > 9n);
  return (11n - sum % 11n) % 10n === account % 10n;
}

/* LB-BEHAVIOR:feature-c10f757d */
/** Finds the first entry with the supplied account number, returning undefined if none exists. */
function findEntry(entries: Entry[], account: bigint): Entry | undefined {
  return entries.find(entry => entry.account === account);
}

/* LB-BEHAVIOR:feature-78ff6cad */
/** Appends an account with its starting balance and C or S kind; returns the original rejection code or zero. */
function appendEntry(entries: Entry[], account: bigint, kind: number, balance: bigint): number {
  if ((kind & 0xef) !== 0x43) return 13;
  if (findEntry(entries, account)) return 23;
  if (entries.length === 64) return 34;
  entries.push({ account, kind, balance, interest: 0n, withdrawals: 0 });
  return 0;
}

/* LB-BEHAVIOR:feature-d1d9a54c */
/** Adds an amount with signed 64-bit wraparound, returning 31 without changing the entry when the resulting balance reaches the limit. */
function addAmount(entry: Entry, amount: bigint): number {
  const balance = signed(entry.balance + amount);
  if (balance >= 1000000000000n) return 31;
  entry.balance = balance;
  return 0;
}

/* LB-BEHAVIOR:feature-ff3a31e5 */
/** Withdraws an amount, enforcing S withdrawal and balance limits or the other mode's overdraft charge; returns a rejection code or zero. */
function subtractAmount(entry: Entry, amount: bigint): number {
  let balance = signed(entry.balance - amount);
  if (entry.kind === 83) {
    if (entry.withdrawals > 5) return 33;
    if (balance < 0n) return 32;
  } else if (balance < 0n) {
    balance = signed(balance - 3500n);
    if (balance < -50000n) return 32;
  }
  entry.balance = balance;
  entry.withdrawals = (entry.withdrawals + 1) | 0;
  return 0;
}

/* LB-BEHAVIOR:feature-7fc46815 */
/** Transfers an amount between distinct entries, restoring the source balance and withdrawal count if the destination rejects it; returns a status code. */
function transferAmount(source: Entry, destination: Entry, amount: bigint): number {
  if (source === destination) return 24;
  const balance = source.balance;
  const withdrawals = source.withdrawals;
  const status = subtractAmount(source, amount);
  if (status !== 0) return status;
  if (addAmount(destination, amount) !== 0) {
    source.balance = balance;
    source.withdrawals = withdrawals;
    return 31;
  }
  return 0;
}

/* LB-BEHAVIOR:feature-927e7754 */
/** Calculates an entry's adjustment from its balance and kind, retaining signed 64-bit intermediate wraparound and division toward zero. */
function scaledValue(entry: Entry): bigint {
  const balance = entry.balance;
  if (balance < 0n) return signed(-(signed(signed(balance * -1800n) + 60000n) / 120000n));
  let rate: bigint;
  if (entry.kind === 83) rate = balance <= 99999n ? 150n : balance < 1000000n ? 275n : 410n;
  else rate = balance > 499999n ? 50n : 0n;
  return signed(signed(rate * balance) + 60000n) / 120000n;
}

/* LB-BEHAVIOR:feature-cddcaa5e */
/** Applies adjustments to all entries, charges low-balance C accounts, and resets withdrawal counts; returns the number of entries. */
function applyAdjustments(entries: Entry[]): number {
  for (const entry of entries) {
    const adjustment = scaledValue(entry);
    const balance = signed(entry.balance + adjustment);
    if (balance < 1000000000000n) {
      entry.balance = balance;
      entry.interest = signed(entry.interest + adjustment);
    }
    if (entry.kind === 67 && entry.balance < 100000n) entry.balance = signed(entry.balance - 500n);
    entry.withdrawals = 0;
  }
  return entries.length;
}

/* LB-BEHAVIOR:feature-ecad0855 */
/** Formats signed integer cents with commas, a right-aligned seventeen-character whole part, and a DB suffix for negatives; keeps native negation wraparound. */
export function formatAmount(amount: bigint): string {
  amount = signed(amount);
  let magnitude = signed(-amount);
  if (magnitude < 0n) magnitude = amount;
  const whole = (magnitude / 100n).toString();
  const padding = Math.max(0, 17 - whole.length - Math.trunc((whole.length - 1) / 3));
  let result = ' '.repeat(padding);
  for (let index = 0; index < whole.length; index++) {
    result += whole[index];
    if (index !== whole.length - 1 && (whole.length - 1 - index) % 3 === 0) result += ',';
  }
  // Conversion to a character retains the low byte, including for the minimum signed value.
  const tens = Number((magnitude % 100n) / 10n) + 48;
  const units = Number(magnitude % 10n) + 48;
  return result + '.' + String.fromCharCode(tens & 255, units & 255) + (amount < 0n ? ' DB' : '');
}

/* LB-BEHAVIOR:feature-73e1a380 */
/** Returns the trial balance in insertion order, with each accumulated interest amount and a signed 64-bit total. */
function printTrialBalance(entries: Entry[]): string {
  let output = 'TRIAL BALANCE\n';
  let total = 0n;
  for (const entry of entries) {
    output += `${entry.account.toString().padStart(8, '0')} ${String.fromCharCode(entry.kind)} ${formatAmount(entry.balance)}\n`;
    output += `           INTEREST ${formatAmount(entry.interest)}\n`;
    total = signed(total + entry.balance);
  }
  return output + `ACCOUNTS ${entries.length}\nTOTAL      ${formatAmount(total)}\n`;
}

