export async function run(input: RunInput, _deps: RunDeps): Promise<RunOutput> {
  const entries: Entry[] = [];
  let output = 'POSTING JOURNAL\n';
  let records = 0;
  let posted = 0;
  let rejected = 0;
  let postedAmount = 0n;
  let cursor = 0;
  while (cursor < input.stdin.length) {
    // fgets consumes at most 127 bytes and includes a terminating newline when present.
    const start = cursor;
    while (cursor < input.stdin.length && cursor - start < 127) {
      if (input.stdin[cursor++] === 10) break;
    }
    const chunk = input.stdin.subarray(start, cursor);
    let length = 0;
    while (length < chunk.length && chunk[length] !== 0 && chunk[length] !== 10 && chunk[length] !== 13) length++;
    const record = chunk.subarray(0, length);
    const code = Array.from(record.subarray(0, 2), byte => String.fromCharCode(byte)).join('');
    records = (records + 1) | 0;
    let account = 0n;
    let amount = 0n;
    let status = 11;
    if (length === 30) {
      if (code === 'ME') {
        applyAdjustments(entries);
        status = 0;
      } else {
        account = parseDecimalSubstring(record, 2, 8);
        const destinationAccount = parseDecimalSubstring(record, 10, 8);
        amount = parseDecimalSubstring(record, 18, 11);
        if ((account | destinationAccount | amount) >= 0n) {
          if (!validateEightDigitMod11Checksum(account)) status = 21;
          else if (code === 'OP') status = appendEntry(entries, account, record[29]!, amount);
          else {
            const source = findEntry(entries, account);
            if (!source) status = 22;
            else if (code === 'DP') status = addAmount(source, amount);
            else if (code === 'WD') status = subtractAmount(source, amount);
            else if (code === 'XF') {
              if (!validateEightDigitMod11Checksum(destinationAccount)) status = 21;
              else {
                const destination = findEntry(entries, destinationAccount);
                status = destination ? transferAmount(source, destination, amount) : 22;
              }
            } else status = 12;
          }
        }
      }
    }
    if (status === 0) {
      posted = (posted + 1) >>> 0;
      postedAmount = signed(postedAmount + amount);
    } else rejected = (rejected + 1) >>> 0;
    output += `${records.toString().padStart(6, '0')} ${code} ${(account < 0n ? 0n : account).toString().padStart(8, '0')} ${formatAmount(amount < 0n ? 0n : amount)} ${status.toString().padStart(2, '0')}\n`;
  }
  output += `RECORDS ${records} POSTED ${posted | 0} REJECTED ${rejected | 0}\nPOSTED     ${formatAmount(postedAmount)}\n`;
  output += printTrialBalance(entries);
  return { stdout: output, exitCode: rejected !== 0 ? 4 : 0 };
